pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BaseEscalationManager} from "../src/BaseEscalationManager.sol";

contract InvMutTest is Test {
    BaseEscalationManager c;

    function setUp() public { c = new BaseEscalationManager(address(this)); }

    function testFuzz_property(bytes32 assertionId) public {

        address nonOptimistic = address(0xBEEF);
        vm.prank(nonOptimistic);
        bool ok;
        try c.assertionDisputedCallback(assertionId) {
            ok = true;
        } catch {
            ok = false;
        }

        vm.prank(nonOptimistic);
        bool ok2;
        try c.requestPrice(assertionId, uint256(1), "") {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        assertTrue(!ok2);
    }
}
